        "az role assignment create --assignee 4c1f6e2a-7d3b-4a59-9c10-2b8e5f3a1d01 --role \"Key Vault Secrets User\" --scope /subscriptions/7f3c2a10-5b4d-4e8a-9c61-0d2e8f1a3b55/resourceGroups/rg-payments/providers/Microsoft.KeyVault/vaults/kv-payments-prod",
        "az role assignment delete --assignee e83b5d19-6a0c-4c7e-b2f4-1d9a7c3e5b03 --role \"Key Vault Secrets Officer\" --scope /subscriptions/7f3c2a10-5b4d-4e8a-9c61-0d2e8f1a3b55/resourceGroups/rg-payments/providers/Microsoft.KeyVault/vaults/kv-payments-prod",
        "az role assignment create --assignee e83b5d19-6a0c-4c7e-b2f4-1d9a7c3e5b03 --role \"Key Vault Secrets User\" --scope /subscriptions/7f3c2a10-5b4d-4e8a-9c61-0d2e8f1a3b55/resourceGroups/rg-payments/providers/Microsoft.KeyVault/vaults/kv-payments-prod",
