            "output": "{\n  \"PolicyVersion\": {\n    \"Document\": {\n      \"Version\": \"2012-10-17\",\n      \"Statement\": [\n        {\n          \"Sid\": \"ReadReports\",\n          \"Effect\": \"Allow\",\n          \"Action\": [\n            \"s3:GetObject\",\n            \"s3:ListBucket\"\n          ],\n          \"Resource\": [\n            \"arn:aws:s3:::acme-reports\",\n            \"arn:aws:s3:::acme-reports/*\"\n          ]\n        },\n        {\n          \"Sid\": \"PassReportRole\",\n          \"Effect\": \"Allow\",\n          \"Action\": \"iam:PassRole\",\n          \"Resource\": \"arn:aws:iam::111122223333:role/report-render-exec\",\n          \"Condition\": {\n            \"StringEquals\": {\n              \"iam:PassedToService\": \"lambda.amazonaws.com\"\n            }\n          }\n        }\n      ]\n    },\n    \"VersionId\": \"v1\",\n    \"IsDefaultVersion\": true,\n    \"CreateDate\": \"2026-05-02T16:55:30+00:00\"\n  }\n}"
